head.script:
scwin.onpageload = function() {
	autoComplete1.setValue("t2");
	dataMap1.set("key1", "t3");

    //autoComplete1
    document.getElementById("mf_autoComplete1_arrow").click();
    var listItems = mf_autoComplete1_itemTable.render.querySelectorAll("li");
    var targetItem = null;

    for (var i = 0; i < listItems.length; i++) {
        if (listItems[i].textContent === "test2") {
            targetItem = listItems[i];
            break;
        }
    }

    if (targetItem) {
        console.log("찾은 요소:", targetItem,targetItem.getAttribute("aria-selected"));
    } else {
        console.log("해당 텍스트를 가진 요소가 없습니다.");
    }

    //autoComplete2
    document.getElementById("mf_autoComplete2_arrow").click();
    var listItems = mf_autoComplete2_itemTable.render.querySelectorAll("li");
    var targetItem = null;

    for (var i = 0; i < listItems.length; i++) {
        if (listItems[i].textContent === "test3") {
            targetItem = listItems[i];
            break;
        }
    }

    if (targetItem) {
        console.log("찾은 요소:", targetItem,targetItem.getAttribute("aria-selected"));
    } else {
        console.log("해당 텍스트를 가진 요소가 없습니다.");
    }
};

scwin.trigger1_onclick = function(e) {

};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('autoComplete1_itemTable_option2').getAttribute('aria-selected') == 'true';
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('autoComplete2_itemTable_option3').getAttribute('aria-selected') == 'true';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
